using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Windows.Forms;

namespace MP1SkinStudio
{
    public static partial class SelfTests
    {
        static SkinProject CollectionDemo(){var p=Demo();p.OpenPage("demo.sammlungen.xml");return p;}
        static SkinControl CollectionControl(SkinProject p,string type){return p.Controls.First(c=>c.Get("type")==type);}
        static void RunCollectionTests(string root)
        {
            Test("Projektformat 4 schützt neue Sammlungsdaten; Format 3 bleibt lesbar",()=>{
                var p=CollectionDemo();string path=Path.Combine(root,"collection-format.mp1skinproj");ProjectFile.Save(p,path);using(var zip=ZipFile.OpenRead(path))using(var reader=new StreamReader(zip.GetEntry("project.xml").Open()))Check(reader.ReadToEnd().Contains("version=\"4\""),"Neues Projekt hat kein Format 4.");RewriteManifest(path,text=>{var doc=new System.Xml.XmlDocument();doc.LoadXml(text);doc.DocumentElement.SetAttribute("version","3");var node=doc.SelectSingleNode("/skinStudioProject/editorState/collection");node.ParentNode.RemoveChild(node);return doc.OuterXml;});Check(ProjectFile.Load(path).Editor.Collection.Mode=="auto","Format 3 nicht kompatibel.");});
            Test("Facade-Navigation verwendet logische ID und schreibt nur die aktive Quellvorlage",()=>{
                var p=CollectionDemo();string key=p.InsertControl("demo.sammlungen.xml","button");var button=p.Controls.First(c=>c.Key==key);var facade=CollectionControl(p,"facadeview");p.ConnectNavigation(button,CollectionControl(p,"listcontrol"),"onright",false);Check(p.NavigationTarget(p.Controls.First(c=>c.Key==key),"onright").Get("type")=="facadeview","Ziel nicht zur Facade aufgelöst.");p.Editor.Collection.Mode="filmstrip";p.ConnectNavigation(CollectionControl(p,"facadeview"),p.Controls.First(c=>c.Key==key),"onleft",false);Check(CollectionControl(p,"filmstrip").Get("onleft")==button.Get("id")&&CollectionControl(p,"listcontrol").Get("onleft")!=button.Get("id"),"Inaktive Vorlage mitbearbeitet.");});
            Test("Native Visibility Hidden und Collapsed bleiben bei Vorschau-Bedingungen unsichtbar",()=>{
                var p=CollectionDemo();var c=p.Controls.First(x=>x.Get("type")=="textbox");c.Properties["Visibility"]=new PropertyValue("Hidden","",true);Check(new PreviewState(p).Visible(c)==false,"Hidden wird sichtbar.");c.Properties["Visibility"]=new PropertyValue("Collapsed","",true);Check(new PreviewState(p).Visible(c)==false,"Collapsed wird sichtbar.");});
            Test("Facade zeigt genau eine Unteransicht und erhält sämtliche XML-Controls",()=>{
                var p=CollectionDemo();int count=p.Controls.Count;string xml=p.Controls[0].Source.Text;foreach(string mode in new[]{"list","smallicons","largeicons","filmstrip","coverflow"}){p.Editor.Collection.Mode=mode;var active=p.Controls.Where(c=>c.RuntimeParent!=null&&c.RuntimeParent.Get("type")=="facadeview"&&CollectionSettings.Active(p,c)).ToArray();Check(active.Length==1&&CollectionSettings.Kind(active[0],mode)==mode,"Mehrere oder falsche Ansichten aktiv.");}Check(count==p.Controls.Count&&xml==p.Controls[0].Source.Text&&!p.Dirty,"Ansichtswechsel verändert XML.");});
            Test("Fehlende Facade-Ansicht fällt auf vorhandene Vorlage zurück",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="playlist";Check(CollectionSettings.EffectiveMode(p)=="list","Fehlende Vorlage wird erfunden.");});
            Test("Facade-Bedingungen und ausgewählte Beispieldaten folgen der Vorschau",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="coverflow";p.Editor.Collection.Focus=2;var state=new PreviewState(p);state.UpdateCollectionValues();Check(state.Evaluate("facadeview.coverflow",new HashSet<string>())==true&&state.Evaluate("facadeview.list",new HashSet<string>())==false&&state.Values["#selecteditem"]==p.Editor.Collection.Items[2].Title&&state.Values["#itemcount"]=="6","Sammlungszustand veraltet.");p.Editor.Preview.Values["#selecteditem"]="Eigener Wert";state=new PreviewState(p);state.UpdateCollectionValues();Check(state.Values["#selecteditem"]=="Eigener Wert","Eigener Beispielwert überschrieben.");});
            Test("Gemeinsame Facade-ID ist eine logische Identität, echte ID-Kollisionen bleiben geschützt",()=>{
                var p=CollectionDemo();Check(p.LogicalControls().Count(c=>c.Get("id")=="50")==1&&new PreviewState(p).Evaluate("control.isvisible(50)",new HashSet<string>())==true,"Facade-Unteransichten erzeugen falsche Mehrdeutigkeit.");Check(!SkinAudit.Run(p).Issues.Any(i=>i.Code=="DUPLICATE_ID"),"Facade-ID wird als Fehler gemeldet.");});
            Test("Listen-Geometrie verwendet textureHeight und spaceBetweenItems",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");var tiles=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);Check(tiles.Length==6&&tiles[1].Bounds.Y-tiles[0].Bounds.Y==95&&tiles[0].Title.X==200&&tiles[0].Detail.X==920,"Zeilenraster oder Textoffsets falsch.");});
            Test("Listenauswahl scrollt in den sichtbaren Bereich ohne XML-Positionen zu ändern",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");p.Editor.Collection.Focus=5;var r=LayoutTools.Bounds(c);r.Height=190;var tiles=CollectionGeometry.Tiles(c,r,p.Editor.Collection);Check(tiles.Length==2&&tiles[0].Index==4&&tiles[1].Index==5&&tiles[1].Selected&&c.Get("posY")=="250","Auswahl außerhalb der sichtbaren Zeilen.");});
            Test("Symbolraster nutzt große Maße getrennt von kleinen Symbolen",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"thumbnailpanel");var small=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);p.Editor.Collection.Mode="largeicons";var big=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);Check(small[0].Bounds.Width==270&&big[0].Bounds.Width==350&&big[0].Image.Width==300,"Große Symbolmaße ignoriert.");});
            Test("Filmstreifen und Coverflow bilden unterschiedliche statische Geometrien",()=>{
                var p=CollectionDemo();var film=CollectionControl(p,"filmstrip");var flow=CollectionControl(p,"coverflow");p.Editor.Collection.Focus=1;var a=CollectionGeometry.Tiles(film,LayoutTools.Bounds(film),p.Editor.Collection);var b=CollectionGeometry.Tiles(flow,LayoutTools.Bounds(flow),p.Editor.Collection);Check(a.Length>1&&a[0].Bounds.Y==a[1].Bounds.Y&&b.Single(t=>t.Selected).Bounds.Width>b.First(t=>!t.Selected).Bounds.Width,"Sammlungsansichten gleichgesetzt.");});
            Test("Leere Sammlung und Auswahl hinter dem letzten Eintrag sind begrenzt",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");p.Editor.Collection.Focus=49;Check(p.Editor.Collection.SelectedIndex==5,"Auswahl nicht begrenzt.");p.Editor.Collection.Items.Clear();Check(p.Editor.Collection.SelectedIndex==-1&&CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection).Length==0,"Leere Sammlung ungültig.");});
            Test("Sammlungsdaten werden tief kopiert und unsichere Bildpfade abgewiesen",()=>{
                var settings=new CollectionSettings();var copy=settings.Copy();copy.Items[0].Title="Neu";Check(settings.Items[0].Title!="Neu","Kopie teilt veränderliche Einträge.");copy.Items[0].Image="../privat.png";Reject(copy.Validate);copy.Items[0].Image="C:\\privat.png";Reject(copy.Validate);});
            Test("Projekt speichert Sammlungsansicht und Daten unabhängig vom Skin-ZIP",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="filmstrip";p.Editor.Collection.Focus=3;p.Editor.Collection.Items[1].Title="Änderung & Test";string signature=ProjectFile.ContentSignature(p);string file=Path.Combine(root,"sammlung.mp1skinproj");ProjectFile.Save(p,file);var loaded=ProjectFile.Load(file);Check(ProjectFile.ContentSignature(loaded)==signature&&loaded.Editor.Collection.Items[1].Title=="Änderung & Test"&&!loaded.Dirty&&loaded.Undo.Count==0,"Sammlungs-Schnappschuss nicht verlustfrei.");p.SetControlText(p.Controls.First(c=>c.Get("type")=="textbox"),"Neuer Text",false);file=Path.Combine(root,"sammlung-export.zip");p.Export(file);using(var zip=ZipFile.OpenRead(file)){Check(zip.Entries.Count==2&&zip.GetEntry("demo.sammlungen.xml")!=null&&zip.GetEntry("_SkinStudio-Hinweise.txt")!=null,"Beispieldaten in Skin-ZIP geraten.");}});
            Test("Schriftgrößen folgen der MP1-Basis von 576 Zeilen",()=>{
                var spec=new SkinFontSpec{Height=24};Check(spec.Pixels(1080)==45&&spec.Pixels(720)==30,"Falsche Schriftgrößenskalierung.");});
            Test("Schriftfamilie, Stil und Alias werden aus fonts.xml geladen",()=>{
                string folder=Path.Combine(root,"font-spec");Directory.CreateDirectory(folder);Write(folder,"fonts.xml","<fonts><font><name>A</name><filename>Segoe UI</filename><height>24</height><bold>yes</bold><italic>yes</italic></font><alias><name>B</name><fontname>A</fontname></alias><alias><name>C</name><fontname>D</fontname></alias><alias><name>D</name><fontname>C</fontname></alias></fonts>");Write(folder,"main.xml",Xml("<label>Text</label>"));var p=new SkinProject(folder);p.OpenPage("main.xml");Check(p.FontSpecs["B"].Family=="Segoe UI"&&p.FontSpecs["B"].Style==(FontStyle.Bold|FontStyle.Italic)&&!p.FontSpecs.ContainsKey("C"),"Fontstil oder Alias-Zyklus falsch.");});
            Test("Textoffsets und Seitenverhältnis bleiben innerhalb des Steuerelements",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");var own=SkinSource.FromText("<control><type>button</type><textXOff>20</textXOff><textYOff>8</textYOff></control>","button.xml");var button=new SkinControl{Node=own.Root};button.Properties["type"]=new PropertyValue("button","",true);button.Properties["textXOff"]=new PropertyValue("20","",true);button.Properties["textYOff"]=new PropertyValue("8","",true);Check(SurfaceGeometry.TextArea(button,new RectangleF(100,200,300,80))==new RectangleF(120,208,260,64),"Textoffsets falsch.");Check(SurfaceGeometry.Fit(new RectangleF(0,0,200,100),new Size(100,100),true)==new RectangleF(50,0,100,100),"Bildproportionen verzerrt.");});
            Test("Bildfärbung berücksichtigt RGB und Alpha ohne Originalgrafik zu verändern",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"textbox");c.Properties["colordiffuse"]=new PropertyValue("80ff0000","",true);using(var canvas=new SkinCanvas{Project=p,State=new PreviewState(p)})using(var image=new Bitmap(8,8))using(var output=new Bitmap(32,32))using(var a=Graphics.FromImage(image))using(var b=Graphics.FromImage(output)){a.Clear(Color.White);canvas.SurfaceImageForTest(b,c,image,new RectangleF(4,4,24,24));var pixel=output.GetPixel(16,16);Check(pixel.R>240&&pixel.G<5&&pixel.B<5&&pixel.A>=125&&pixel.A<=130&&image.GetPixel(4,4).ToArgb()==Color.White.ToArgb(),"Bildfärbung oder Alpha falsch.");}});
            Test("Textbox-Zeilenumbruch zeichnet zusätzliche Zeilen und hält die Begrenzung ein",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"textbox");using(var canvas=new SkinCanvas{Project=p,State=new PreviewState(p)})using(var output=new Bitmap(240,220))using(var g=Graphics.FromImage(output)){canvas.SurfaceTextForTest(g,c,"Langer Text mit mehreren Wörtern und mehreren Zeilen für die Vorschau",new RectangleF(20,20,180,180));bool lower=false;for(int y=70;y<200;y++)for(int x=20;x<200;x++)if(output.GetPixel(x,y).A>0)lower=true;Check(lower&&output.GetPixel(2,2).A==0&&output.GetPixel(220,200).A==0,"Kein Zeilenumbruch oder Text außerhalb des Felds.");}});
        }
    }
    public sealed partial class SkinCanvas
    {
        internal void SurfaceImageForTest(Graphics g,SkinControl c,Bitmap image,RectangleF rect){SurfaceImage(g,c,image,rect);}
        internal void SurfaceTextForTest(Graphics g,SkinControl c,string text,RectangleF rect){SurfaceText(g,c,text,rect,false,"font","textcolor","align",true);}
    }
    public sealed partial class StudioForm
    {
        void RunCollectionUiSmoke(string directory,Action<bool,string> verify)
        {
            PrepareCollectionPreview("list");var facade=project.Controls.First(c=>c.Get("type")=="facadeview");SelectControl(facade);string xml=facade.Source.Text,signature=ProjectFile.XmlSignature(project);
            verify(canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="listcontrol"))&&!canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="filmstrip")),"Facade zeigt nur die aktive Unteransicht in der Arbeitsfläche");
            using(var dialog=new CollectionDialog(project.Editor.Collection)){dialog.Show(this);Application.DoEvents();dialog.ConfigureForTest("coverflow",2,"Ein Film | 2026 | Studio/Symbol-Film.png\r\nNoch ein Film | 2025 | Studio/Symbol-Bilder.png");dialog.SubmitForTest();ApplyCollectionSettings(dialog.Result);}
            verify(CollectionSettings.EffectiveMode(project)=="coverflow"&&state.Values["#selecteditem"]=="Noch ein Film"&&canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="coverflow")),"Sammlungsdialog übernimmt Ansicht, Auswahl und eigene Daten");
            verify(ProjectFile.XmlSignature(project)==signature&&project.Undo.Count==0&&!project.Dirty&&SessionNeedsSaving(),"Sammlungszustand wird unabhängig von XML und Undo zum Sichern vorgemerkt");
            string file=Path.Combine(directory,"Sammlung.mp1skinproj");SaveSession(file);ResumeSession(file);verify(project.Editor.Collection.Mode=="coverflow"&&project.Editor.Collection.Focus==1&&project.Editor.Collection.Items.Count==2&&!SessionNeedsSaving(),"Projektöffnung stellt Sammlungszustand und Sicherungsstatus wieder her");
            using(var dialog=new CollectionDialog(project.Editor.Collection)){dialog.ConfigureForTest("list",1,"Test | Zusatz | ../nicht-erlaubt.png");bool rejected=false;try{dialog.CollectForTest();}catch{rejected=true;}verify(rejected&&project.Editor.Collection.Mode=="coverflow","Sammlungsdialog verwirft ungültige Bildpfade vor der Übernahme");}
            selected=project.Controls.First(c=>c.Get("type")=="facadeview");SelectControl(selected);bool seen=false;using(var timer=new Timer{Interval=30}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.OfType<CollectionDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();seen=true;dialog.DialogResult=DialogResult.Cancel;dialog.Close();};var menu=(StudioMenu)ProtectionMenu();int index=menu.Items.Cast<ToolStripItem>().ToList().FindIndex(i=>i.Text.StartsWith("Sammlungs-Vorschau",StringComparison.Ordinal));timer.Start();menu.Show(tree,new Point(10,10));menu.ChooseForTest(index);timer.Stop();}verify(seen&&project.Editor.Collection.Mode=="coverflow"&&!SessionNeedsSaving(),"Element-Menü öffnet Sammlungsdialog; Abbrechen verändert keine Daten");
            PrepareCollectionPreview("largeicons");RenderTo(Path.Combine(directory,"Sammlung-Grosse-Symbole.png"));Show();Application.DoEvents();verify(project.Controls[0].Source.Text==xml,"Gerenderte Sammlung erhält Original-XML");
            LoadProject(DemoRoot(),"demo.xml");SelectControl(project.Controls.First(c=>c.Name=="Filme"));string original=selected.Source.Text;fields["textXOff"].Text="25";fields["textYOff"].Text="10";fields["textalign"].Text="right";fields["textvalign"].Text="middle";Apply();verify(selected.Get("textXOff")=="25"&&selected.Get("textalign")=="right"&&SurfaceGeometry.TextArea(selected,canvas.BoundsOf(selected)).X==canvas.BoundsOf(selected).X+25,"Textabstände und innere Ausrichtung lassen sich über Eigenschaften atomar bearbeiten");undo.PerformClick();verify(selected.Source.Text==original&&!project.Dirty,"Undo der Textdarstellung stellt Quelltext exakt wieder her");
        }
    }
}
